private static function truncate(float $number, int $digits): float
{
    $formatted = sprintf('%.14E', $number);
    [$mantissa, $exponent] = explode('E', $formatted);
    $exponent = (int) $exponent;
    $digitString = str_replace('.', '', $mantissa);

    $keep = $exponent + $digits + 1;
    if ($keep <= 0) {
        return 0.0;
    }
    if ($keep > 15) {
        $keep = 15;
    }

    return (int) substr($digitString, 0, $keep) * 10 ** ($exponent - $keep + 1);
}

